-- GH Bucketlist — catalog seed for public.listings (generated from the mock data).
-- Run in the Supabase SQL Editor after marketplace.sql. Safe to re-run (upsert).

on conflict (id) do update set
  kind = excluded.kind, host_id = excluded.host_id, slug = excluded.slug, title = excluded.title,
  city = excluded.city, category = excluded.category, price_from = excluded.price_from,
  rating = excluded.rating, data = excluded.data, updated_at = now();
